UPDATE companies SET description='The Amish Chair Company operates as a division of P.E. O’Halloran in Ellsworth, Maine. The business handcrafts outdoor furniture using Amish craftsmen and traditional woodworking techniques passed down through generations.

The company produces Adirondack chairs, rockers, lawn chairs, log chairs, picnic tables, barn wood furniture, dining room sets, and bedroom sets. Each piece is built by hand from solid white cedar or poly lumber, with joinery and finishes designed to withstand Maine’s four seasons. A showroom displays the full line.

Customers are served throughout Hancock County and across Maine, including Bar Harbor, Bangor, Brewer, Newport, Waterville, Augusta, and Portland.

The company emphasizes that white cedar naturally resists rot, insects, and decay, while its poly lumber won’t crack, splinter, warp, or fade — a combination chosen for the coastal climate. The use of generational Amish craftsmanship is presented as the core differentiator.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Outdoor Furniture", "Barn Wood Furniture", "Picnic Tables", "Chair Swings", "Dining Room Sets", "Bedroom Sets", "Traditional woodworking", "White cedar fabrication", "Poly lumber fabrication"], "industries": [], "materials": ["White cedar", "Poly lumber"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted by Amish craftsmen using traditional woodworking techniques", "Solid white cedar that naturally resists rot, insects, and decay", "Poly lumber that won\u2019t crack, splinter, warp, or fade", "Finishes made to hold up to Maine\u2019s four seasons", "Showroom in Ellsworth serving customers across Maine"], "facts_used": ["Located in Ellsworth, Maine -> /", "Division of P.E. O\u2019Halloran -> /", "Handcrafted by Amish craftsmen using traditional woodworking techniques -> /", "Materials: solid white cedar and poly lumber -> /", "Products: Adirondack chairs, rockers, lawn chairs, log chairs, picnic tables -> /", "Showroom at 525 Bangor Road -> /", "Serves customers throughout Hancock County and across Maine -> /", "White cedar resists rot, insects, decay -> /", "Poly lumber won''t crack, splinter, warp, or fade -> /", "Capabilities: Outdoor Furniture, Barn Wood Furniture, Picnic Tables, Chair Swings, Dining Room Sets, Bedroom Sets -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "our outdoor furniture is handcrafted by skilled Amish craftsmen using solid white cedar and durable poly lumber", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, update