UPDATE companies SET description='Tucson Custom Sheet Metal operates from a shop in Tucson, Arizona.

The shop produces both stock and custom sheet metal roofing products, including flashing, scuppers, vents, cooler jacks, caps, and pipe jacks. Core processes include cutting, bending, and soldering; scupper and jack joints are fully soldered for water-tight seals. The facility stocks material in gauges ranging from 28GA to 20GA, with 20GA representing the maximum thickness the equipment can cut and bend. Copper and other premium metals are available by special request.

The company maintains a stock inventory of standard flashing, scuppers, and vents for immediate pickup or quick shipment, while also fabricating custom pieces for unique project requirements.

The business emphasizes durability, noting that its products are made to last with fully soldered, water-tight joints. It positions itself as a local supplier capable of fulfilling both standard orders from stock and custom fabrications with short lead times for the Tucson market.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Sheet metal cutting", "Sheet metal bending", "Soldering", "Custom fabrication", "Stock inventory management", "Roofing product manufacturing"], "industries": ["Roofing"], "materials": ["Copper"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Located in Tucson, Arizona -> /", "Serving Tucson for over 30 years -> /", "Manufactures custom and stock sheet metal roofing products (flashing, scuppers, vents, cooler jacks, caps, pipe jacks) -> /", "Stocks sheet metal gauges 28GA through 20GA -> /", "Offers copper and other premium metals upon request -> /", "Scupper and jack joints fully soldered and water tight -> /", "Shop hours 6:30am - 3:00pm -> /", "Address: 3635 Refinery Way, Tucson, AZ 85713 -> /", "Headquarters city and state from database -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Your premier local supplier for custom and stock sheet metal roofing products.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tucson-custom-sheet-metal' AND approved AND profile IS NULL;
UPDATE companies SET description='Turn-Key Medical is based in Meridian, Idaho, and has been providing diagnostic imaging services for over 40 years. The company became 100% employee-owned in 2019, joining a group of employee-owned organizations in the region.

The company sells, installs, and services a range of medical imaging systems, including computed tomography (CT), X-ray, magnetic resonance imaging (MRI), ultrasound, angiography/interventional, women''s health, C-arms, fluoroscopy, enterprise imaging, molecular imaging, and mammography. It also supplies accessories and provides applications support. Turn-Key Medical maintains a local parts depot at its Meridian headquarters and has service specialists positioned across its territory to minimize response times for mission-critical equipment.

Its vendor partnerships include Canon Medical, Novarad, QT Ultrasound, Orthoscan, and Ziehm, allowing it to configure systems for specific clinical needs.

